class Solution {
    long long MOD = 1e9 + 7;
    long long power(long long base, long long exp) {
        long long res = 1;
        base %= MOD;
        while (exp > 0) {
            if (exp & 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }
public:
    int numberOfInfectionSequences(int n, vector<int>& sick) {
        vector<int> gaps, interior;
        if (sick[0] > 0) gaps.push_back(sick[0]);
        for (int i = 1; i < sick.size(); i++) {
            int l = sick[i] - sick[i - 1] - 1;
            if (l > 0) {
                gaps.push_back(l);
                interior.push_back(l);
            }
        }
        if (sick.back() < n - 1) gaps.push_back(n - 1 - sick.back());
        int tot = 0;
        for (int x : gaps) tot += x;
        vector<long long> fact(tot + 1, 1);
        for (int i = 1; i <= tot; i++) fact[i] = (fact[i - 1] * i) % MOD;
        long long ans = fact[tot];
        for (int l : gaps) ans = (ans * power(fact[l], MOD - 2)) % MOD;
        for (int l : interior) ans = (ans * power(2, l - 1)) % MOD;
        return ans;
    }
};

