    public int numberOfInfectionSequences(int n, int[] sick) {
        List<Integer> gaps = new ArrayList<>();
        List<Integer> interior = new ArrayList<>();
        if (sick[0] > 0) gaps.add(sick[0]);
        for (int i = 1; i < sick.length; i++) {
            int l = sick[i] - sick[i - 1] - 1;
            if (l > 0) {
                gaps.add(l);
                interior.add(l);
            }
        }
        if (sick[sick.length - 1] < n - 1) gaps.add(n - 1 - sick[sick.length - 1]);
        int tot = 0;
        for (int x : gaps) tot += x;
        long[] fact = new long[tot + 1];
        fact[0] = 1;
        for (int i = 1; i <= tot; i++) fact[i] = (fact[i - 1] * i) % MOD;
        long ans = fact[tot];
        for (int l : gaps) ans = (ans * power(fact[l], MOD - 2)) % MOD;
        for (int l : interior) ans = (ans * power(2, l - 1)) % MOD;
