var numberOfInfectionSequences = function(n, sick) {
    const MOD = 1000000007n;
    function power(base, exp) {
        let res = 1n;
        base = BigInt(base) % MOD;
        let e = BigInt(exp);
        while (e > 0n) {
            if ((e & 1n) === 1n) res = (res * base) % MOD;
            base = (base * base) % MOD;
            e >>= 1n;
        }
        return res;
    }
    const gaps = [], interior = [];
    if (sick[0] > 0) gaps.push(sick[0]);
    for (let i = 1; i < sick.length; i++) {
        const l = sick[i] - sick[i - 1] - 1;
        if (l > 0) {
            gaps.push(l);
            interior.push(l);
        }
    }
    if (sick[sick.length - 1] < n - 1) gaps.push(n - 1 - sick[sick.length - 1]);
    let tot = 0;
    for (const x of gaps) tot += x;
    const fact = new BigInt64Array(tot + 1);
    fact[0] = 1n;
    for (let i = 1; i <= tot; i++) fact[i] = (fact[i - 1] * BigInt(i)) % MOD;
    let ans = fact[tot];
    for (const l of gaps) ans = (ans * power(fact[l], MOD - 2n)) % MOD;
    for (const l of interior) ans = (ans * power(2n, l - 1)) % MOD;
    return Number(ans);
};
